// ==UserScript==
// @name         HP video to Connector
// @namespace    http://tampermonkey.net/
// @version      1.2
// @description  Extract videos from HP support pages with Connector Helper
// @author       You
// @match        https://support.hp.com/us-en/document*
// @grant        none
// ==/UserScript==

(function() {
  'use strict';

const styles = `
#tutorial-modal { position: fixed; top: 20px; right: 20px; background: white; border-radius: 8px; padding: 16px; box-shadow: 0 4px 20px rgba(0,0,0,0.3); z-index: 10003; max-width: 400px; opacity: 0; transform: translateY(-100px); transition: opacity 0.4s ease, transform 0.4s ease; pointer-events: none; }
#tutorial-modal.active { opacity: 1; transform: translateY(0); pointer-events: auto; }
#tutorial-modal img { width: 100%; height: auto; border-radius: 4px; }
#helper-modal .modal-content { background:white; border-radius:8px; width:100%; max-width:400px; max-height:90vh; overflow-y:auto; padding:20px; display:flex; flex-direction:column; align-items:center; box-shadow:0 4px 20px rgba(0,0,0,0.2); }
#helper-modal .helper-btn { width:100%; text-align:center; }.helper-btn.copied { color: #000 !important; font-weight: 700; background: #e8f5e9 !important; }
#extract-btn { position: fixed; top: 20px; right: 20px; padding: 10px 16px; background: #0096d6; color: white; border: none; border-radius: 4px; cursor: pointer; font-weight: 500; z-index: 10000; }
#extract-btn:hover { background: #0078b4; }
#video-modal, #helper-modal { display: flex; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.6); z-index: 10001; align-items: center; justify-content: center; padding: 20px; opacity: 0; pointer-events: none; transition: opacity 0.3s ease, background 0.3s ease; }
#video-modal.active, #helper-modal.active { opacity: 1; pointer-events: auto; background: rgba(0,0,0,0.97); }
.modal-content { background: white; border-radius: 8px; width: 100%; max-height: 85vh; overflow-y: auto; padding: 0; display: flex; flex-direction: column; box-shadow: 0 4px 20px rgba(0,0,0,0.2); transform: scale(0.95) translateY(-20px); transition: transform 0.3s ease; opacity: 0; }
#video-modal.active .modal-content, #helper-modal.active .modal-content { transform: scale(1) translateY(0); opacity: 1; }
.notification { position: fixed; bottom: 24px; right: 24px; background: white; color: #333; padding: 16px 24px; border-radius: 8px; box-shadow: 0 4px 20px rgba(0,0,0,0.15); font-size: 14px; font-weight: 500; z-index: 10002; animation: slideIn 0.3s ease forwards, slideOut 0.3s ease 2.7s forwards; display: flex; align-items: center; gap: 12px; }
.notification.success { border-left: 4px solid #4caf50; }
.notification.error { border-left: 4px solid #f44336; }
.notification-icon { font-size: 18px; }
@keyframes slideIn { from { transform: translateX(400px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
@keyframes slideOut { from { transform: translateX(0); opacity: 1; } to { transform: translateX(400px); opacity: 0; } }
.modal-content.single-video { max-width: 350px; }
.modal-content.multiple-videos { max-width: none; width: auto; min-width: 600px; }
.modal-content.no-videos { max-width: 450px; }
.modal-header { display: flex; justify-content: space-between; align-items: center; padding: 24px; border-bottom: 1px solid #e5e5e5; flex-shrink: 0; }
.modal-header h2 { margin: 0; font-size: 22px; font-weight: 600; }
.close-btn { background: none; border: none; font-size: 28px; cursor: pointer; color: #999; padding: 0; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; }
.close-btn:hover { color: #333; }
.videos-container { padding: 24px; overflow-y: auto; flex: 1; display: flex; justify-content: center; }
.videos-grid { display: flex; flex-wrap: nowrap; gap: 20px; overflow-x: auto; padding-bottom: 10px; }
.video-card { flex: 0 0 250px; border: 1px solid #e5e5e5; border-radius: 8px; overflow: hidden; display: flex; flex-direction: column; transition: box-shadow 0.2s; background: #fafafa; }
.video-card:hover { box-shadow: 0 2px 12px rgba(0,0,0,0.1); }
.video-thumbnail { width: 100%; height: auto; object-fit: contain; display: block; }
.video-details { padding: 14px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.video-title { font-weight: 600; font-size: 13px; line-height: 1.5; color: #222; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.video-id-label { font-size: 11px; color: #999; text-transform: uppercase; letter-spacing: 0.5px; }
.video-id { font-size: 18px; color: #000; font-family: 'Courier New', monospace; font-weight: 700; word-break: break-all; }
.select-btn { padding: 10px 16px; background: #0096d6; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 13px; font-weight: 500; margin-top: auto; transition: background 0.2s; }
.select-btn:hover { background: #0078b4; }
.empty-state { text-align: center; padding: 60px 20px; color: #999; }
.helper-btn { padding:10px 16px; font-size:13px; cursor:pointer; background:#0096d6; color:white; border:none; border-radius:4px; margin-bottom:10px; width: 100%; text-align: center; font-weight: 500; transition: background 0.3s ease; position: relative; }
.helper-btn:hover { background: #0078b4; }
.helper-btn .checkmark { display: none; position: absolute; right: 10px; top: 50%; transform: translateY(-50%); color: #4caf50; font-size: 24px; }
.helper-btn.clicked .checkmark { display: inline; }
.helper-header { display: flex; justify-content: space-between; align-items: center; width: 100%; gap: 10px; margin-bottom: 20px; }
.helper-header h2 { margin: 0; font-size: 18px; font-weight: 600; flex: 1; }
.video-id-section { background: #f5f5f5; padding: 12px; border-radius: 4px; display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 20px; width: 100%; }
.video-id-section .video-id { margin: 0; }
.copy-vid-btn { padding: 6px 12px; background: #0096d6; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 12px; font-weight: 500; white-space: nowrap; transition: background 0.2s; }
.copy-vid-btn:hover { background: #0078b4; }
#helper-modal .close-btn { width: 100%; text-align: center; padding: 10px 16px; background: #f0f0f0; color: #333; margin-top: 20px; font-size: 16px; border-radius: 4px; }
#helper-modal .close-btn:hover { background: #e0e0e0; }
`;

const connectorSteps = {
    stepsBeforeVideo: "a2luZDogU2V0VGV4dFZhcmlhYmxlDQppZDogeSBDWVVaZQ0KdmFyaWFibGU6IFRvcGljLnN0ZXBzQmVmb3JlVmlkZW8NCnZhbHVlOiBTdGVwcyBiZWZvcmUgdmlkZW8gZ29lcyBoZXJlICEgUGxlYXNlIGRlbGV0ZSB0aGlzIGFuZCBhZGQgeW91ciBzdGVwcw0K",
    stepsAfterVideo: "a2luZDogU2V0VGV4dFZhcmlhYmxlDQppZDogU2ZuMVR6DQp2YXJpYWJsZTogVG9waWMuc3RlcHNBZnRlclZpZGVvDQp2YWx1ZTogU3RlcHMgYWZ0ZXIgdmlkZW8gZ29lcyBoZXJlICEgUGxlYXNlIGRlbGV0ZSB0aGlzIGFuZCBhZGQgeW91ciBzdGVwcw==",
    collectionId: "a2luZDogU2V0VmFyaWFibGUNCmlkOiBOcUQwY3kNCnZhcmlhYmxlOiBUb3BpYy5jb2xsZWN0aW9uSWQNCnZhbHVlOiBBZGQgdGhlIENJRCBoZXJlICE=",
    getVideoContent: "",
    getVideoContentRecord: "",
    conditionElements: "",
    otherConditionAdaptive: ""
  };

const tutorialImages = {
  stepsBeforeVideo: "data:image/png;base64,",
  stepsAfterVideo: "data:image/png;base64,",
  collectionId: "data:image/png;base64,",
  getVideoContent: "data:image/png;base64,",
  getVideoContentRecord: "data:image/png;base64,",
  conditionElements: "data:image/png;base64,",
  otherConditionAdaptive: "data:image/png;base64,"
};

function injectStyles() {
    const styleSheet = document.createElement('style');
    styleSheet.textContent = styles;
    document.head.appendChild(styleSheet);}

function extractVideos() {
    const videos = [];
    const containers = document.querySelectorAll('.bcSingleVideoContainer');

    containers.forEach(container => {
      const id = container.getAttribute('id') || container.getAttribute('data-id');
      const titleEl = container.querySelector('.video-title');
      const imgEl = container.querySelector('.thumbnail-img');

      if (id && titleEl) {
        videos.push({
          id: id,
          title: titleEl.textContent.trim(),
          thumbnail: imgEl ? imgEl.src : ''
        });
      }
    });

    return videos;
  }

function closeModal(modal) {
    modal.classList.remove('active');
  }

function showNotification(message, type = 'success') {
    const notification = document.createElement('div');
    notification.className = `notification ${type}`;
    notification.innerHTML = `
      <span class="notification-icon">${type === 'success' ? '✓' : '✕'}</span>
      <span>${message}</span>
    `;
    document.body.appendChild(notification);

    setTimeout(() => {
      notification.remove();
    }, 3000);
  }

function showModal(videos) {
    const modal = document.getElementById('video-modal');
    const modalContent = document.querySelector('#video-modal .modal-content');

    modalContent.classList.remove('single-video', 'multiple-videos', 'no-videos');
    if (videos.length === 0) modalContent.classList.add('no-videos');
    else if (videos.length === 1) modalContent.classList.add('single-video');
    else modalContent.classList.add('multiple-videos');

    let html = `
      <div class="modal-header">
        <h2>Videos Found (${videos.length})</h2>
        <button class="close-btn">&times;</button>
      </div>
    `;

    if (videos.length === 0) html += `<div class="empty-state">No videos found in this page.</div>`;
    else {
      html += `<div class="videos-container"><div class="videos-grid">`;
      videos.forEach(video => {
        html += `
          <div class="video-card">
            ${video.thumbnail ? `<img src="${video.thumbnail}" alt="${video.title}" class="video-thumbnail">` : ''}
            <div class="video-details">
              <div class="video-title">${video.title}</div>
              <div>
                <div class="video-id-label">Video ID</div>
                <div class="video-id">${video.id}</div>
              </div>
              <button class="select-btn select-video-btn" data-video-id="${video.id}">Select</button>
            </div>
          </div>
        `;
      });
      html += `</div></div>`;
    }

    modalContent.innerHTML = html;

    modalContent.querySelectorAll('.select-video-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const videoId = btn.dataset.videoId;
        closeModal(modal);
        showConnectorHelper(videoId);
      });
    });

    modalContent.querySelector('.close-btn').addEventListener('click', () => closeModal(modal));
    modal.addEventListener('click', e => { if (e.target === modal) closeModal(modal); });

    modal.classList.add('active');
  }

function showConnectorHelper(videoId) {
    const helperModal = document.getElementById('helper-modal');
    const helperContent = helperModal.querySelector('.modal-content');

    helperContent.innerHTML = '';
    helperModal.classList.remove('active');

    let helperHtml = `
      <div class="modal-header">
        <div class="helper-header">
          <h2>Connector Helper</h2>
        </div>
      </div>
      <div style="padding: 20px; width: 100%;">
        <div class="video-id-section">
          <span class="video-id" style="flex: 1;">${videoId}</span>
          <button class="copy-vid-btn" data-copy="${videoId}">Copy</button>
        </div>
    `;

    const buttonLabels = {
      stepsBeforeVideo: 'Steps Before Video',
      stepsAfterVideo: 'Steps After Video',
      collectionId: 'Collection Id',
      getVideoContent: 'Get Video Content',
      getVideoContentRecord: 'Get Video Content Record',
      conditionElements: 'Condition Elements',
      otherConditionAdaptive: 'Other Condition (Adaptive)'
    };

    for (const key of Object.keys(buttonLabels)) {
      helperHtml += `<button class="helper-btn" data-key="${key}" data-original-label="${buttonLabels[key]}">${buttonLabels[key]}<span class="checkmark">✓</span></button>`;
    }

    helperHtml += `</div><button class="close-btn">Close</button>`;
    helperContent.innerHTML = helperHtml;

    helperContent.querySelector('.copy-vid-btn').addEventListener('click', () => {
      navigator.clipboard.writeText(videoId)
        .then(() => showNotification(`Video ID copied!`))
        .catch(err => showNotification('Failed to copy ID', 'error'));
    });

    helperContent.querySelectorAll('.helper-btn').forEach(btn => {
      btn.classList.remove('clicked');
      btn.addEventListener('click', () => {
        const key = btn.dataset.key;
        const originalLabel = btn.dataset.originalLabel;
        if (!connectorSteps[key]) return showNotification(`${buttonLabels[key]} is empty!`, 'error');
navigator.clipboard.writeText(atob(connectorSteps[key])).then(() => {
          btn.textContent = 'COPIED !';
          btn.classList.add('clicked', 'copied');
          showTutorialModal(key);

          setTimeout(() => {
            btn.innerHTML = `${originalLabel}<span class="checkmark">✓</span>`;
            btn.classList.remove('copied');
          }, 2000);
        });
      });
    });

    helperContent.querySelector('.close-btn').addEventListener('click', () => {
      helperContent.innerHTML = '';
      closeTutorialModal();
      closeModal(helperModal);
    });
    helperModal.addEventListener('click', e => {
      if (e.target === helperModal) {
        helperContent.innerHTML = '';
        closeTutorialModal();
        closeModal(helperModal);
      }
    });

    helperModal.classList.add('active');
  }

function showTutorialModal(key) {
    const tutorialModal = document.getElementById('tutorial-modal');
    const img = tutorialModal.querySelector('img');

    if (tutorialImages[key]) {
      if (tutorialModal.classList.contains('active')) {
        tutorialModal.classList.remove('active');

        setTimeout(() => {
          img.src = tutorialImages[key];
          setTimeout(() => {
            tutorialModal.classList.add('active');
          }, 50);
        }, 100);
      } else {
        img.src = tutorialImages[key];
        setTimeout(() => {
          tutorialModal.classList.add('active');
        }, 50);
      }
    }
  }

function closeTutorialModal() {
    const tutorialModal = document.getElementById('tutorial-modal');
    tutorialModal.classList.remove('active');
  }

function init() {
    injectStyles();

    const btn = document.createElement('button');
    btn.id = 'extract-btn';
    btn.textContent = 'Connector helper';
    btn.addEventListener('click', () => showModal(extractVideos()));
    document.body.appendChild(btn);

    const modal = document.createElement('div');
    modal.id = 'video-modal';
    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';
    modal.appendChild(modalContent);
    document.body.appendChild(modal);

    const helperModal = document.createElement('div');
    helperModal.id = 'helper-modal';
    const helperContent = document.createElement('div');
    helperContent.className = 'modal-content';
    helperModal.appendChild(helperContent);
    document.body.appendChild(helperModal);

const tutorialModal = document.createElement('div');
    tutorialModal.id = 'tutorial-modal';
    tutorialModal.className = 'tutorial-modal';
    tutorialModal.innerHTML = `
      <img src="" alt="Tutorial">
    `;
    document.body.appendChild(tutorialModal);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();

})();
